/*
 * odk_unicode.c - Unicode text layer runtime.
 *
 * Implements the text layer (docs/TEXT-MODES.md) on top of the committed UCD 15.1.0
 * tables (odk_unicode_data.c, generated by the project's table generator):
 *
 *   - strict UTF-8 decoding (odk_u_decode_next / odk_utf8_decode_next)
 *   - NFC normalization + Unicode default case folding (odk_u_normalize)
 *   - class/script lookups, White_Space predicates
 *   - script-aware segmentation tokenizer (odk_extract_tokens_ex)
 *   - code-point trigram counter (odk_u_trigram_counter)
 *   - code-point-correct truncation/strip helpers
 *
 * Determinism: no locale, no towlower/tolower, no wall clock, no RNG.
 * Every allocation is checked; failures unwind to the caller (OOM in
 * normalization fails the operation; it never silently degrades).
 *
 * The ASCII fast path: any text consisting only of bytes < 0x80 skips
 * the Unicode machinery entirely and reuses the legacy byte loop, which
 * keeps ASCII_COMPAT output byte-exact by construction
 * (NFC and default folding are the identity on pure ASCII).
 *
 */

#include "odk_internal.h"
#include "odk_unicode_internal.h"
#include "odk_lang.h"

#include <stdlib.h>
#include <string.h>

/* ------------------------------------------------------------------ */
/* Code point array helper                                             */
/* ------------------------------------------------------------------ */

typedef struct {
    uint32_t *cps;
    size_t count;
    size_t cap;
} cp_array;

static int cp_push(cp_array *a, uint32_t cp)
{
    if (a->count == a->cap) {
        size_t grown_cap = a->cap ? a->cap * 2 : 64;
        uint32_t *grown;
        if (grown_cap > SIZE_MAX / sizeof(uint32_t)) {
            return -1;
        }
        grown = realloc(a->cps, grown_cap * sizeof(uint32_t));
        if (grown == NULL) {
            return -1;
        }
        a->cps = grown;
        a->cap = grown_cap;
    }
    a->cps[a->count++] = cp;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Strict UTF-8 decoding                                     */
/* ------------------------------------------------------------------ */

int odk_u_decode_next(const char *s, size_t len, uint32_t *out_cp)
{
    unsigned char b0;
    unsigned char b1;
    unsigned char b2;
    unsigned char b3;

    if (s == NULL || len == 0) {
        return 0;
    }
    b0 = (unsigned char)s[0];
    if (b0 < 0x80) {
        *out_cp = b0;
        return 1;
    }
    if (b0 < 0xC2 || b0 > 0xF4) {
        return 0; /* stray continuation, C0/C1 overlong leads, F5-FF */
    }
    if (b0 < 0xE0) { /* C2..DF + 1 continuation */
        if (len < 2) {
            return 0;
        }
        b1 = (unsigned char)s[1];
        if ((b1 & 0xC0) != 0x80) {
            return 0;
        }
        *out_cp = ((uint32_t)(b0 & 0x1F) << 6) | (uint32_t)(b1 & 0x3F);
        return 2;
    }
    if (b0 < 0xF0) { /* E0..EF + 2 continuations */
        if (len < 3) {
            return 0;
        }
        b1 = (unsigned char)s[1];
        b2 = (unsigned char)s[2];
        if ((b1 & 0xC0) != 0x80 || (b2 & 0xC0) != 0x80) {
            return 0;
        }
        if (b0 == 0xE0 && b1 < 0xA0) {
            return 0; /* overlong */
        }
        if (b0 == 0xED && b1 >= 0xA0) {
            return 0; /* surrogate D800..DFFF */
        }
        *out_cp = ((uint32_t)(b0 & 0x0F) << 12) |
                  ((uint32_t)(b1 & 0x3F) << 6) | (uint32_t)(b2 & 0x3F);
        return 3;
    }
    /* F0..F4 + 3 continuations */
    if (len < 4) {
        return 0;
    }
    b1 = (unsigned char)s[1];
    b2 = (unsigned char)s[2];
    b3 = (unsigned char)s[3];
    if ((b1 & 0xC0) != 0x80 || (b2 & 0xC0) != 0x80 ||
        (b3 & 0xC0) != 0x80) {
        return 0;
    }
    if (b0 == 0xF0 && b1 < 0x90) {
        return 0; /* overlong */
    }
    if (b0 == 0xF4 && b1 > 0x8F) {
        return 0; /* > U+10FFFF */
    }
    *out_cp = ((uint32_t)(b0 & 0x07) << 18) |
              ((uint32_t)(b1 & 0x3F) << 12) |
              ((uint32_t)(b2 & 0x3F) << 6) | (uint32_t)(b3 & 0x3F);
    return 4;
}

/* Public wrapper: 1-4 bytes consumed, 0 = invalid byte. */
int odk_utf8_decode_next(const char *s, size_t len, uint32_t *out_cp)
{
    if (s == NULL || out_cp == NULL) {
        return 0;
    }
    return odk_u_decode_next(s, len, out_cp);
}

uint32_t *odk_u_decode_all(const char *s, size_t len, size_t *out_count)
{
    cp_array a;
    size_t i = 0;

    a.cps = NULL;
    a.count = 0;
    a.cap = 0;
    *out_count = 0;
    if (len == 0) {
        /* Empty input returns a VALID (non-NULL, count 0)
         * array.  Callers distinguish NULL only as allocation
         * failure; a language layer that strips every code point
         * (e.g. a lone tashkeel under ar) must not be mistaken for
         * OOM.  The baseline paths never reach here with len 0 (the
         * ASCII fast path returns first), so the anchor is safe. */
        a.cps = malloc(sizeof(uint32_t));
        return a.cps;
    }
    while (i < len) {
        uint32_t cp;
        int used = odk_u_decode_next(s + i, len - i, &cp);
        if (used == 0) {
            cp = 0xFFFFFFFFu; /* invalid byte marker = separator */
            used = 1;
        }
        if (cp_push(&a, cp) != 0) {
            free(a.cps);
            return NULL;
        }
        i += (size_t)used;
    }
    *out_count = a.count;
    return a.cps;
}

/* UTF-8 encode one code point; returns the byte count.  Values that
 * cannot encode (never produced by the strict decoder) become U+FFFD
 * so the encoder itself is total. */
static int cp_encode(uint32_t cp, char out[4])
{
    if (cp < 0x80) {
        out[0] = (char)cp;
        return 1;
    }
    if (cp < 0x800) {
        out[0] = (char)(0xC0 | (cp >> 6));
        out[1] = (char)(0x80 | (cp & 0x3F));
        return 2;
    }
    if (cp < 0x10000) {
        if (cp >= 0xD800 && cp <= 0xDFFF) {
            cp = 0xFFFD; /* defensive */
        } else {
            out[0] = (char)(0xE0 | (cp >> 12));
            out[1] = (char)(0x80 | ((cp >> 6) & 0x3F));
            out[2] = (char)(0x80 | (cp & 0x3F));
            return 3;
        }
    }
    if (cp <= 0x10FFFF) {
        out[0] = (char)(0xF0 | (cp >> 18));
        out[1] = (char)(0x80 | ((cp >> 12) & 0x3F));
        out[2] = (char)(0x80 | ((cp >> 6) & 0x3F));
        out[3] = (char)(0x80 | (cp & 0x3F));
        return 4;
    }
    out[0] = (char)0xEF;
    out[1] = (char)0xBF;
    out[2] = (char)0xBD;
    return 3;
}

/* ------------------------------------------------------------------ */
/* Table lookups                                                       */
/* ------------------------------------------------------------------ */

unsigned char odk_u_class(uint32_t cp)
{
    if (cp < 0x10000) {
        return odk_class_blocks[odk_class_stage1_bmp[cp >> 7]][cp & 0x7F];
    }
    if (cp < 0x110000) {
        /* sparse supplementary ranges (binary search) */
        size_t lo = 0;
        size_t hi = odk_class_supra_count;
        while (lo < hi) {
            size_t mid = lo + (hi - lo) / 2;
            if ((uint32_t)odk_class_supra[mid].last < cp) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        if (lo < odk_class_supra_count &&
            (uint32_t)odk_class_supra[lo].first <= cp) {
            return odk_class_blocks[odk_class_supra[lo].block][cp & 0x7F];
        }
    }
    return (unsigned char)(ODK_S_INHERIT << 4); /* unassigned = other */
}

int odk_u_is_letter(uint32_t cp)
{
    return (odk_u_class(cp) & ODK_U_LETTER) != 0;
}

int odk_u_is_mark(uint32_t cp)
{
    return (odk_u_class(cp) & ODK_U_MARK) != 0;
}

int odk_u_is_number(uint32_t cp)
{
    return (odk_u_class(cp) & ODK_U_NUMBER) != 0;
}

int odk_u_is_space(uint32_t cp)
{
    return (odk_u_class(cp) & ODK_U_SPACE) != 0;
}

unsigned char odk_u_script(uint32_t cp)
{
    return (unsigned char)(odk_u_class(cp) & ODK_U_SCRIPT_MASK) >> 4;
}

/* script_class is the NIBBLE value (ODK_S_*), not a shifted byte. */
int odk_u_is_bigram_script(unsigned char script_class)
{
    switch (script_class) {
    case ODK_S_HAN:
    case ODK_S_HIRA:
    case ODK_S_KATA:
    case ODK_S_THAI:
    case ODK_S_LAO:
    case ODK_S_KHMR:
    case ODK_S_MYAN:
        return 1;
    default:
        return 0;
    }
}

const unsigned int *odk_u_decomp(uint32_t cp, int *out_len)
{
    size_t lo = 0;
    size_t hi = odk_dec_cp_count;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (odk_dec_cp[mid] < cp) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    if (lo < odk_dec_cp_count && odk_dec_cp[lo] == cp) {
        size_t base = 0;
        size_t i;
        for (i = 0; i < lo; i++) {
            base += odk_dec_len[i];
        }
        *out_len = odk_dec_len[lo];
        return &odk_dec_data[base];
    }
    *out_len = 0;
    return NULL;
}

int odk_u_ccc(uint32_t cp)
{
    size_t lo = 0;
    size_t hi = odk_ccc_cp_count;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (odk_ccc_cp[mid] < cp) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    if (lo < odk_ccc_cp_count && odk_ccc_cp[lo] == cp) {
        return odk_ccc_val[lo];
    }
    return 0;
}

uint32_t odk_u_compose(uint32_t first, uint32_t second)
{
    size_t lo = 0;
    size_t hi = odk_compose_count;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (odk_compose_a[mid] < first ||
            (odk_compose_a[mid] == first && odk_compose_b[mid] < second)) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    if (lo < odk_compose_count && odk_compose_a[lo] == first &&
        odk_compose_b[lo] == second) {
        return odk_compose_c[lo];
    }
    return 0;
}

int odk_u_fold(uint32_t cp, uint32_t out[3])
{
    size_t lo = 0;
    size_t hi = odk_fold_cp_count;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (odk_fold_cp[mid] < cp) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    if (lo < odk_fold_cp_count && odk_fold_cp[lo] == cp) {
        size_t base = 0;
        size_t i;
        int n = odk_fold_len[lo];
        for (i = 0; i < lo; i++) {
            base += odk_fold_len[i];
        }
        for (i = 0; i < (size_t)n; i++) {
            out[i] = odk_fold_data[base + i];
        }
        return n;
    }
    return 0;
}

int odk_u_needs_nfc(uint32_t cp)
{
    if (cp >= 0x110000) {
        return 0;
    }
    return (odk_needs_nfc[cp >> 10] >> ((cp >> 7) & 7)) & 1;
}

/* Dense per-cp guards.  A CLEAR bit proves (from the
 * committed tables) that the cp is not decomposable, has ccc 0 and
 * never appears as a composition second - so the corresponding table
 * searches would return the identity/miss results directly.  cps at
 * or above the limit always take the slow path (correct, slower). */
static int nfc_dense_bit(uint32_t cp)
{
    if (cp >= odk_nfc_dense_limit) {
        return 1; /* unknown: slow path */
    }
    return (odk_nfc_dense_bmp[cp >> 3] >> (cp & 7)) & 1;
}

/* Clear bit proves the cp has no case-fold entry. */
static int fold_dense_bit(uint32_t cp)
{
    if (cp >= odk_fold_dense_limit) {
        return 1; /* unknown: slow path */
    }
    return (odk_fold_dense_bmp[cp >> 3] >> (cp & 7)) & 1;
}

/* ------------------------------------------------------------------ */
/* NFC (mirrors the generator's MiniNFC, validated externally)       */
/* ------------------------------------------------------------------ */

#define HANGUL_SBASE 0xAC00u
#define HANGUL_LCOUNT 19u
#define HANGUL_VCOUNT 21u
#define HANGUL_TCOUNT 28u
#define HANGUL_NCOUNT (HANGUL_VCOUNT * HANGUL_TCOUNT)
#define HANGUL_SCOUNT (HANGUL_LCOUNT * HANGUL_NCOUNT)
#define HANGUL_LBASE 0x1100u
#define HANGUL_VBASE 0x1161u
#define HANGUL_TBASE 0x11A7u

/* Recursive canonical decomposition with a defensive depth cap (the
 * real UCD closure depth is <= 4; the cap only guards a corrupted
 * table). */
static int nfc_decompose(uint32_t cp, cp_array *out, int depth)
{
    const unsigned int *parts;
    int len = 0;
    int i;

    if (depth > 16) {
        return cp_push(out, cp);
    }
    if (cp >= HANGUL_SBASE && cp < HANGUL_SBASE + HANGUL_SCOUNT) {
        uint32_t s = cp - HANGUL_SBASE;
        uint32_t lp = s / HANGUL_NCOUNT;
        uint32_t vp = (s % HANGUL_NCOUNT) / HANGUL_TCOUNT;
        uint32_t tp = s % HANGUL_TCOUNT;
        if (cp_push(out, HANGUL_LBASE + lp) != 0 ||
            cp_push(out, HANGUL_VBASE + vp) != 0) {
            return -1;
        }
        if (tp != 0) {
            return cp_push(out, HANGUL_TBASE + tp);
        }
        return 0;
    }
    parts = odk_u_decomp(cp, &len);
    if (parts != NULL) {
        for (i = 0; i < len; i++) {
            if (nfc_decompose(parts[i], out, depth + 1) != 0) {
                return -1;
            }
        }
        return 0;
    }
    return cp_push(out, cp);
}

/* stable insertion sort of one starter group by combining class */
static void sort_group(uint32_t *cps, size_t n)
{
    size_t i;
    for (i = 1; i < n; i++) {
        uint32_t key = cps[i];
        int key_ccc = odk_u_ccc(key);
        size_t j = i;
        while (j > 0 && odk_u_ccc(cps[j - 1]) > key_ccc) {
            cps[j] = cps[j - 1];
            j--;
        }
        cps[j] = key;
    }
}

/* In-place NFC of a code point array.  On success returns the new
 * length and sets *out_ok = 1; on allocation failure sets *out_ok = 0
 * (the array contents are then undefined - the caller must fail the
 * operation, never use the half-normalized data). */
size_t odk_u_nfc_array(const uint32_t *cps, size_t count,
                        uint32_t **out_result, int *out_ok)
{
    cp_array decomposed;
    uint32_t *out = NULL;
    size_t out_len = 0;
    size_t i;
    long last_starter;
    int last_ccc;

    *out_ok = 1;
    *out_result = NULL;
    /* quick skip: nothing needs NFC - copy verbatim into a fresh buffer
     * so the caller ALWAYS owns a malloc'd result of the returned
     * length (the earlier in-place contract overflowed whenever canonical
     * decomposition expanded the sequence - found by fuzzing). */
    {
        int any = 0;
        for (i = 0; i < count; i++) {
            if (odk_u_needs_nfc(cps[i])) {
                any = 1;
                break;
            }
        }
        if (!any) {
            uint32_t *copy = malloc((count ? count : 1) *
                                    sizeof(uint32_t));
            if (copy == NULL) {
                *out_ok = 0;
                return count;
            }
            memcpy(copy, cps, count * sizeof(uint32_t));
            *out_result = copy;
            return count;
        }
    }

    decomposed.cps = NULL;
    decomposed.count = 0;
    decomposed.cap = 0;
    for (i = 0; i < count; i++) {
        if (!nfc_dense_bit(cps[i])) {
            /* proved: no decomposition, ccc 0, never a compose second */
            if (cp_push(&decomposed, cps[i]) != 0) {
                free(decomposed.cps);
                *out_ok = 0;
                return count;
            }
            continue;
        }
        if (nfc_decompose(cps[i], &decomposed, 0) != 0) {
            free(decomposed.cps);
            *out_ok = 0;
            return count;
        }
    }

    /* canonical ordering: stable-sort each starter group (the group of
     * non-starters that follows each starter) */
    {
        size_t start = 0;
        for (i = 0; i <= decomposed.count; i++) {
            if (i == decomposed.count ||
                (!nfc_dense_bit(decomposed.cps[i])
                     ? 0
                     : odk_u_ccc(decomposed.cps[i])) == 0) {
                if (i > start) {
                    sort_group(decomposed.cps + start, i - start);
                }
                start = i + 1;
            }
        }
    }

    /* composition (UAX #15): the current starter absorbs every
     * following char that is not blocked (intervening char with
     * ccc >= ccc(current)); Hangul L+V and LV+T are algorithmic. */
    out = malloc((decomposed.count ? decomposed.count : 1) *
                 sizeof(uint32_t));
    if (out == NULL) {
        free(decomposed.cps);
        *out_ok = 0;
        return count;
    }
    (void)out_len;
    last_starter = -1;
    last_ccc = 0;
    for (i = 0; i < decomposed.count; i++) {
        uint32_t cp = decomposed.cps[i];
        int dense = nfc_dense_bit(cp);
        int c = dense ? odk_u_ccc(cp) : 0;
        int composed = 0;
        if (last_starter >= 0 && (last_ccc == 0 || last_ccc < c)) {
            uint32_t base = out[last_starter];
            uint32_t comp = 0;
            if (base >= HANGUL_LBASE && base <= HANGUL_LBASE + 18 &&
                cp >= HANGUL_VBASE && cp <= HANGUL_VBASE + 20) {
                comp = HANGUL_SBASE +
                       (base - HANGUL_LBASE) * HANGUL_NCOUNT +
                       (cp - HANGUL_VBASE) * HANGUL_TCOUNT;
            } else if (base >= HANGUL_SBASE &&
                       base < HANGUL_SBASE + HANGUL_SCOUNT &&
                       (base - HANGUL_SBASE) % HANGUL_TCOUNT == 0 &&
                       cp > HANGUL_TBASE && cp <= HANGUL_TBASE + 27) {
                comp = base + (cp - HANGUL_TBASE);
            } else if (dense) {
                /* proved for clear bits: cp is not a composition second,
                 * so the pair search would miss */
                comp = odk_u_compose(base, cp);
            }
            if (comp != 0) {
                out[last_starter] = comp;
                composed = 1; /* cp consumed; last_ccc unchanged */
            }
        }
        if (!composed) {
            out[out_len++] = cp;
            last_ccc = c;
            if (c == 0) {
                last_starter = (long)out_len - 1;
            }
        }
    }

    free(decomposed.cps);
    *out_result = out;
    return out_len;
}

/* ------------------------------------------------------------------ */
/* fold(NFC(text)) pipeline                                   */
/* ------------------------------------------------------------------ */

static int text_is_ascii(const char *s, size_t len)
{
    size_t i;
    for (i = 0; i < len; i++) {
        if ((unsigned char)s[i] >= 0x80) {
            return 0;
        }
    }
    return 1;
}

char *odk_u_normalize_len(const char *text, size_t len)
{
    uint32_t *cps = NULL;
    size_t count = 0;
    int ok = 0;
    cp_array folded;
    sb_t sb;
    size_t i;

    if (text == NULL) {
        return odk_strdup("");
    }
    if (text_is_ascii(text, len)) {
        /* NFC is the identity on ASCII, but default case folding is
         * ASCII lowercasing (A-Z -> a-z), so the pipeline lowercases. */
        char *out = odk_strdup_range(text, len);
        if (out != NULL) {
            size_t k;
            for (k = 0; k < len; k++) {
                if (out[k] >= 'A' && out[k] <= 'Z') {
                    out[k] = (char)(out[k] - 'A' + 'a');
                }
            }
        }
        return out;
    }
    cps = odk_u_decode_all(text, len, &count);
    if (cps == NULL) {
        return NULL;
    }
    {
        uint32_t *nfc = NULL;
        count = odk_u_nfc_array(cps, count, &nfc, &ok);
        free(cps);
        cps = nfc;
    }
    if (!ok || cps == NULL) {
        free(cps);
        return NULL;
    }

    folded.cps = NULL;
    folded.count = 0;
    folded.cap = 0;
    for (i = 0; i < count; i++) {
        uint32_t mapping[3];
        int n;
        if (!fold_dense_bit(cps[i])) {
            /* proved: no fold entry - identity */
            if (cp_push(&folded, cps[i]) != 0) {
                goto oom;
            }
            continue;
        }
        n = odk_u_fold(cps[i], mapping);
        {
            int k;
            if (n == 0) {
                if (cp_push(&folded, cps[i]) != 0) {
                    goto oom;
                }
            } else {
                for (k = 0; k < n; k++) {
                    if (cp_push(&folded, mapping[k]) != 0) {
                        goto oom;
                    }
                }
            }
        }
    }

    if (sb_init(&sb) != 0) {
        goto oom;
    }
    for (i = 0; i < folded.count; i++) {
        char enc[4];
        int n = cp_encode(folded.cps[i], enc);
        if (sb_append(&sb, enc, (size_t)n) != 0) {
            sb_free(&sb);
            goto oom;
        }
    }
    free(folded.cps);
    free(cps);
    return sb_detach(&sb);

oom:
    free(folded.cps);
    free(cps);
    return NULL;
}

char *odk_u_normalize(const char *text)
{
    return odk_u_normalize_len(text, text != NULL ? strlen(text) : 0);
}

/* Language-aware normalization.  UND/AUTO/DEFAULT
 * are the exact baseline pipeline (identity anchor); a concrete
 * language applies the generic layer (width/spaces/bidi/apostrophes)
 * plus the per-language fold (Arabic/Urdu variant + presentation
 * forms) and the pack's digit folding, all in odk_lang.c. */
char *odk_u_normalize_lang(const char *text, odk_language lang)
{
    size_t len = text != NULL ? strlen(text) : 0;
    uint32_t *cps = NULL;
    uint32_t *lang_cps = NULL;
    size_t count = 0;
    size_t n;
    char *base;
    char *out;
    int fold_digits;

    if (text == NULL) {
        return odk_strdup("");
    }
    if (lang == ODK_LANG_UND || lang == ODK_LANG_AUTO ||
        lang == ODK_LANG_DEFAULT) {
        return odk_u_normalize_len(text, len);
    }
    if (text_is_ascii(text, len)) {
        /* ASCII input: the generic + language layers only touch
         * apostrophes (U+2019 etc. - absent in pure ASCII), so the
         * baseline ASCII fast path is already the correct result. */
        return odk_u_normalize_len(text, len);
    }

    base = odk_u_normalize_len(text, len);
    if (base == NULL) {
        return NULL;
    }
    cps = odk_u_decode_all(base, strlen(base), &count);
    free(base);
    if (cps == NULL) {
        return NULL;
    }
    lang_cps = malloc((count * 2 + 1) * sizeof(uint32_t));
    if (lang_cps == NULL) {
        free(cps);
        return NULL;
    }
    n = odk_lang_normalize(cps, count, lang, lang_cps, count * 2 + 1);
    if (n == (size_t)-1) {
        free(cps);
        free(lang_cps);
        return NULL;
    }
    fold_digits = odk_lang_digit_folding_default(lang);
    if (fold_digits) {
        size_t i;
        for (i = 0; i < n; i++) {
            lang_cps[i] = odk_lang_fold_digit(lang_cps[i], 1);
        }
    }
    free(cps);

    /* re-encode */
    {
        char buf[4];
        sb_t sb;
        size_t i;
        if (sb_init(&sb) != 0) {
            free(lang_cps);
            return NULL;
        }
        for (i = 0; i < n; i++) {
            int cl = cp_encode(lang_cps[i], buf);
            if (sb_append(&sb, buf, (size_t)cl) != 0) {
                sb_free(&sb);
                free(lang_cps);
                return NULL;
            }
        }
        free(lang_cps);
        out = sb_detach(&sb);
    }
    return out;
}

/* Public: fold(NFC(text)) as a malloc'd string. */
char *odk_text_normalize_alloc(const char *text)
{
    return odk_u_normalize(text);
}

/* ------------------------------------------------------------------ */
/* Strip / truncate helpers (code-point aware)                         */
/* ------------------------------------------------------------------ */

void odk_u_strip_bounds(const char *s, size_t len, size_t *start,
                        size_t *end)
{
    size_t lo = 0;
    size_t hi = len;

    if (s == NULL) {
        *start = 0;
        *end = 0;
        return;
    }
    /* forward: skip leading White_Space code points */
    while (lo < hi) {
        uint32_t cp;
        int used = odk_u_decode_next(s + lo, hi - lo, &cp);
        if (used > 0 && odk_u_is_space(cp)) {
            lo += (size_t)used;
        } else {
            break; /* invalid bytes are not space */
        }
    }
    /* backward: skip trailing White_Space code points */
    while (hi > lo) {
        size_t seq_start = hi - 1;
        size_t k;
        uint32_t cp;
        int used;
        for (k = 1; k <= 3 && seq_start > lo; k++) {
            if (((unsigned char)s[hi - 1 - k] & 0xC0) != 0x80) {
                seq_start = hi - 1 - k;
                break;
            }
            seq_start = hi - 1 - k;
        }
        if (seq_start >= hi) { /* defensive; cannot happen */
            break;
        }
        used = odk_u_decode_next(s + seq_start, hi - seq_start, &cp);
        if (used > 0 && (size_t)used == hi - seq_start && odk_u_is_space(cp)) {
            hi = seq_start;
        } else {
            break;
        }
    }
    *start = lo;
    *end = hi;
}

size_t odk_u_truncate_cp(const char *s, size_t len, size_t n_cps)
{
    size_t i = 0;
    size_t cps = 0;
    if (s == NULL || n_cps == 0) {
        return 0;
    }
    while (i < len && cps < n_cps) {
        uint32_t cp;
        int used = odk_u_decode_next(s + i, len - i, &cp);
        if (used == 0) {
            used = 1;
        }
        i += (size_t)used;
        cps++;
    }
    return i; /* whole sequences only */
}

/* Whitespace span helper: bytes consumed when s[0] starts a
 * White_Space code point (0 when not whitespace). */
int odk_u_space_span(const char *s, size_t len)
{
    uint32_t cp;
    int used;
    if (s == NULL || len == 0) {
        return 0;
    }
    used = odk_u_decode_next(s, len, &cp);
    if (used > 0 && odk_u_is_space(cp)) {
        return used;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Stopword packs                                                      */
/* ------------------------------------------------------------------ */

/* The English pack is the legacy kStopwords[] in odk_util.c, reused via a
 * bridge so the pack stays byte-identical to the legacy behavior. */
int odk_util_stopword_en_find(const char *s); /* odk_util.c */

int odk_stopword_is_stop(odk_stopword_pack pack, const char *token)
{
    const char *const *words = NULL;
    size_t count = 0;
    size_t lo;
    size_t hi;

    switch (pack) {
    case ODK_STOPWORDS_NONE:
        return 0;
    case ODK_STOPWORDS_EN:
        return odk_util_stopword_en_find(token);
    case ODK_STOPWORDS_DE:
        words = odk_stopwords_de;
        count = odk_stopwords_de_count;
        break;
    case ODK_STOPWORDS_FR:
        words = odk_stopwords_fr;
        count = odk_stopwords_fr_count;
        break;
    case ODK_STOPWORDS_ES:
        words = odk_stopwords_es;
        count = odk_stopwords_es_count;
        break;
    default:
        return 0;
    }
    lo = 0;
    hi = count;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        int cmp = strcmp(token, words[mid]);
        if (cmp == 0) {
            return 1;
        }
        if (cmp < 0) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Segmentation tokenizer                                     */
/* ------------------------------------------------------------------ */

static int push_token_cp(const uint32_t *cps, size_t n, str_list_t *out)
{
    char buf[4];
    sb_t sb;
    size_t i;
    int rc;

    if (sb_init(&sb) != 0) {
        return -1;
    }
    for (i = 0; i < n; i++) {
        int len = cp_encode(cps[i], buf);
        if (sb_append(&sb, buf, (size_t)len) != 0) {
            sb_free(&sb);
            return -1;
        }
    }
    rc = str_list_push(out, sb.data, sb.len);
    sb_free(&sb);
    return rc;
}

static int push_pair_cp(uint32_t a, uint32_t b, str_list_t *out)
{
    uint32_t pair[2];
    pair[0] = a;
    pair[1] = b;
    return push_token_cp(pair, 2, out);
}

/* ASCII text with a non-EN pack: run the legacy tokenizer unfiltered and
 * apply this pack's own filter; when a language is set it also applies the LANGUAGE pack
 * filter (additive). */
static int tokens_ascii_pack(const char *text, odk_stopword_pack pack,
                             odk_language lang, const odk_rt_text *rt,
                             int morph_light, int filtered,
                             str_list_t *out);

/* UNICODE post-filter (see definition below); it
 * takes the language for the additive pack filter. */
static int unicode_post_filter(const str_list_t *in, odk_stopword_pack pack,
                               odk_language lang, const odk_rt_text *rt,
                               int strip_joiners, int morph_light,
                               str_list_t *out);

/* Zh hybrid mode compile switch (default OFF = bigram mode,
 * the baseline behavior).  Build with -DODK_ZH_HYBRID=1 to
 * emit overlapping bigrams PLUS single-cp tokens for Han characters
 * outside the (stopword-pack) function-word set. */
#ifndef ODK_ZH_HYBRID
#define ODK_ZH_HYBRID 0
#endif

#if ODK_ZH_HYBRID
static int zh_single_is_function_word(uint32_t cp)
{
    char one[8];
    int len = cp_encode(cp, one);
    if (len <= 0) {
        return 1;
    }
    one[len] = '\0';
    return odk_lang_is_stop(ODK_LANG_ZH, one);
}
#endif

/* The stopword oracle.  A runtime-loaded list
 * REPLACES the compiled-in packs (legacy enum pack + language pack);
 * with no runtime list the two compiled-in checks are exactly the
 * baseline/language-layer behavior (rt == NULL anchor). */
static int lang_stop_hit(odk_stopword_pack pack, odk_language lang,
                         const odk_rt_text *rt, const char *tok)
{
    if (rt != NULL && rt->stopwords != NULL) {
        return odk_lang_rt_is_stop(rt, tok);
    }
    if (odk_stopword_is_stop(pack, tok)) {
        return 1;
    }
#if defined(ODK_ABLATE_NO_LANG_STOP)
    /* dev-only ablation toggle: language-pack
     * stopwords off (the EN stopword pack above is NOT affected -
     * it is the baseline path). */
    (void)lang;
    return 0;
#else
    return lang != ODK_LANG_UND && odk_lang_is_stop(lang, tok);
#endif
}

static int tokens_ascii_pack(const char *text, odk_stopword_pack pack,
                             odk_language lang, const odk_rt_text *rt,
                             int morph_light, int filtered,
                             str_list_t *out)
{
    str_list_t raw;
    size_t k;

    str_list_init(&raw);
    if (odk_extract_tokens(text, 0, &raw) != 0) {
        str_list_free(&raw);
        return -1;
    }
    for (k = 0; k < raw.count; k++) {
        const char *tok = raw.items[k];
        size_t tok_len = strlen(tok);
        char *owned = NULL;
        const char *eff = tok;
        size_t eff_len = tok_len;
        /* Light morphology in the matching channel; the
         * token only allocates when the rule actually shortens it. */
        if (filtered && morph_light && tok_len > 0 && tok_len < 256) {
            char tmp[256];
            size_t ml;
            memcpy(tmp, tok, tok_len);
            tmp[tok_len] = '\0';
            ml = odk_lang_morph_light(lang, tmp, tok_len);
            if (ml != tok_len) {
                owned = malloc(ml + 1);
                if (owned == NULL) {
                    str_list_free(&raw);
                    str_list_free(out);
                    return -1;
                }
                memcpy(owned, tmp, ml);
                owned[ml] = '\0';
                eff = owned;
                eff_len = ml;
            }
        }
        if (filtered && eff_len <= 1) {
            free(owned);
            continue;
        }
        if (filtered && lang_stop_hit(pack, lang, rt, eff)) {
            free(owned);
            continue;
        }
        if (str_list_push(out, eff, eff_len) != 0) {
            free(owned);
            str_list_free(&raw);
            str_list_free(out);
            return -1;
        }
        free(owned);
    }
    str_list_free(&raw);
    return 0;
}

/* Core: language-aware tokenizer.  lang is the
 * RESOLVED language (AUTO -> concrete per text, resolved by the
 * public wrappers below).  UND keeps the exact baseline behavior
 * (identity anchor). */
static int extract_tokens_core(const char *text, odk_text_mode mode,
                               odk_stopword_pack pack, odk_language lang,
                               const odk_rt_text *rt, int morph_light,
                               int filtered, str_list_t *out)
{
    uint32_t *cps = NULL;
    unsigned char *eff = NULL; /* effective script nibble per cp */
    size_t count = 0;
    size_t run_start;
    int failed = 0;
    const int zwj_join = odk_lang_zwj_join(lang);

    str_list_init(out);
    if (text == NULL) {
        return 0;
    }

    /* ASCII paths: byte-identical to legacy for the EN pack + UND
     * (identity anchor); other packs (and languages) reuse the same byte
     * loop with their own filter. */
    {
        int pure_ascii = 1;
        size_t len = strlen(text);
        size_t i;
        for (i = 0; i < len; i++) {
            if ((unsigned char)text[i] >= 0x80) {
                pure_ascii = 0;
                break;
            }
        }
        if (pure_ascii || mode == ODK_TEXT_ASCII_COMPAT) {
            if (pack == ODK_STOPWORDS_EN && lang == ODK_LANG_UND) {
                return odk_extract_tokens(text, filtered, out);
            }
            return tokens_ascii_pack(text, pack, lang, rt, morph_light,
                                    filtered, out);
        }
    }

    /* UNICODE mode, non-ASCII text: decode + fold(NFC(.)) + language
     * layer (odk_u_normalize_lang is the baseline pipeline for UND) */
    {
        char *normalized = odk_u_normalize_lang(text, lang);
        if (normalized == NULL) {
            return -1;
        }
        cps = odk_u_decode_all(normalized, strlen(normalized), &count);
        free(normalized);
        if (cps == NULL) {
            return -1;
        }
    }

    eff = malloc(count ? count : 1);
    if (eff == NULL) {
        free(cps);
        return -1;
    }

    run_start = 0;
    while (run_start < count && !failed) {
        size_t run_end;
        if ((odk_u_class(cps[run_start]) & (ODK_U_LETTER | ODK_U_MARK |
                                            ODK_U_NUMBER)) == 0) {
            run_start++;
            continue;
        }
        run_end = run_start;
        while (run_end < count) {
            if ((odk_u_class(cps[run_end]) & (ODK_U_LETTER | ODK_U_MARK |
                                              ODK_U_NUMBER)) != 0) {
                run_end++;
                continue;
            }
            /* Gap 2: ZWJ/ZWNJ flanked by letters/marks on BOTH
             * sides joins the token (LF_ZWJ_JOIN packs; UAX #29-style).
             * UND keeps the baseline separator behavior (identity anchor).
             * Digits do NOT flank: "42<ZWNJ>db" stays two
             * tokens.  The joiner itself is KEPT in the emitted run;
             * the matching channel (unicode_post_filter) strips it. */
            if (zwj_join &&
                (cps[run_end] == 0x200Cu || cps[run_end] == 0x200Du) &&
                run_end > run_start &&
                (odk_u_class(cps[run_end - 1]) &
                 (ODK_U_LETTER | ODK_U_MARK)) != 0 &&
                run_end + 1 < count &&
                (odk_u_class(cps[run_end + 1]) &
                 (ODK_U_LETTER | ODK_U_MARK)) != 0) {
                run_end += 2;
                continue;
            }
            break;
        }

        /* effective scripts inside [run_start, run_end): forward then
         * backward pass */
        {
            unsigned char prev = ODK_S_INHERIT;
            unsigned char next = ODK_S_WORD;
            size_t k;
            for (k = run_start; k < run_end; k++) {
                unsigned char own = odk_u_script(cps[k]);
                if (own != ODK_S_INHERIT) {
                    prev = own;
                    eff[k] = own;
                } else {
                    eff[k] = prev;
                }
            }
            for (k = run_end; k > run_start; k--) {
                unsigned char own = odk_u_script(cps[k - 1]);
                if (own != ODK_S_INHERIT) {
                    next = own;
                } else if (eff[k - 1] == ODK_S_INHERIT) {
                    eff[k - 1] = next;
                }
            }
        }

        /* split at effective-script changes and emit */
        {
            size_t seg_start = run_start;
            size_t k;
            for (k = run_start + 1; k <= run_end; k++) {
                if (k == run_end || eff[k] != eff[seg_start]) {
                    unsigned char script = eff[seg_start];
                    size_t seg_len = k - seg_start;
                    if (odk_u_is_bigram_script(script)) {
                        if (rt != NULL && rt->zh_words != NULL
                            && rt->zh_word_count > 0
                            && lang == ODK_LANG_ZH) {
                            /* Zh lexicon mode:
                             * forward maximum matching against the
                             * runtime-loaded word list; unmatched
                             * positions fall back to single-cp tokens
                             * (which the bigram-script exemption in
                             * unicode_post_filter keeps). */
                            size_t pos = seg_start;
                            while (pos < k) {
                                size_t maxn = k - pos;
                                size_t best = 0;
                                if (maxn > rt->zh_word_max_cps) {
                                    maxn = rt->zh_word_max_cps;
                                }
                                while (maxn >= 2) {
                                    if (odk_lang_zh_word_match(
                                            rt, cps + pos, maxn)) {
                                        best = maxn;
                                        break;
                                    }
                                    maxn--;
                                }
                                if (best == 0) {
                                    if (push_token_cp(&cps[pos], 1,
                                                      out) != 0) {
                                        failed = 1;
                                        break;
                                    }
                                    pos++;
                                } else {
                                    if (push_token_cp(cps + pos, best,
                                                      out) != 0) {
                                        failed = 1;
                                        break;
                                    }
                                    pos += best;
                                }
                            }
                            if (failed) {
                                break;
                            }
                        } else if (seg_len == 1) {
                            if (push_token_cp(&cps[seg_start], 1, out) != 0) {
                                failed = 1;
                                break;
                            }
                        } else {
                            size_t m;
                            for (m = seg_start; m + 1 < k; m++) {
                                if (push_pair_cp(cps[m], cps[m + 1],
                                                 out) != 0) {
                                    failed = 1;
                                    break;
                                }
                            }
                            if (failed) {
                                break;
                            }
#if ODK_ZH_HYBRID
                            /* Zh hybrid mode (compile flag,
                             * default OFF = bigram mode, the baseline
                             * behavior): bigrams PLUS
                             * single-cp tokens for Han characters
                             * outside the function-word set (the zh
                             * stopword-pack singles). */
                            if (lang == ODK_LANG_ZH) {
                                size_t m2;
                                for (m2 = seg_start; m2 < k; m2++) {
                                    if (!zh_single_is_function_word(
                                            cps[m2])) {
                                        if (push_token_cp(&cps[m2], 1,
                                                          out) != 0) {
                                            failed = 1;
                                            break;
                                        }
                                    }
                                }
                                if (failed) {
                                    break;
                                }
                            }
#endif
                        }
                    } else {
                        if (push_token_cp(&cps[seg_start], seg_len,
                                          out) != 0) {
                            failed = 1;
                            break;
                        }
                    }
                    seg_start = k;
                }
            }
        }
        run_start = run_end;
    }

    free(eff);
    free(cps);
    if (failed) {
        str_list_free(out);
        return -1;
    }

    /* post-filter (filtered mode): keep tokens with > 1 code point,
     * except single-cp tokens of bigram scripts; then pack stopwords
     * and, when a language is set, language-pack stopwords.
     * Joiners (U+200C/U+200D) inside joined tokens are stripped here
     * for the MATCHING channel (display/raw tokens keep them). */
    if (filtered) {
        str_list_t kept;
        if (unicode_post_filter(out, pack, lang, rt, zwj_join,
                                morph_light, &kept) != 0) {
            str_list_free(out);
            return -1;
        }
        str_list_free(out);
        *out = kept;
    }
    return 0;
}

/* Public entry points.  odk_extract_tokens_ex keeps the exact
 * baseline signature and semantics (UND); odk_extract_tokens_lang
 * resolves AUTO per text via the conservative detector. */
int odk_extract_tokens_ex(const char *text, odk_text_mode mode,
                          odk_stopword_pack pack, int filtered,
                          str_list_t *out)
{
    return extract_tokens_core(text, mode, pack, ODK_LANG_UND, NULL, 0,
                               filtered, out);
}

int odk_extract_tokens_lang(const char *text, odk_text_mode mode,
                            odk_stopword_pack pack, odk_language lang,
                            const odk_rt_text *rt, int filtered,
                            str_list_t *out)
{
    odk_language resolved = odk_lang_resolve(lang, text);
    return extract_tokens_core(text, mode, pack, resolved, rt, 0,
                               filtered, out);
}

/* Does this token contain a ZWJ/ZWNJ byte sequence
 * (E2 80 8C / E2 80 8D)?  Used by the matching-channel joiner
 * strip (display tokens keep them; LANGUAGES.md). */
static int token_has_joiner(const char *tok, size_t len)
{
    size_t b;
    for (b = 0; b + 2 < len; b++) {
        if ((unsigned char)tok[b] == 0xE2 &&
            (unsigned char)tok[b + 1] == 0x80 &&
            ((unsigned char)tok[b + 2] == 0x8C ||
             (unsigned char)tok[b + 2] == 0x8D)) {
            return 1;
        }
    }
    return 0;
}

/* Copy of the token without the joiner sequences (matching
 * form).  Returns a malloc'd NUL-terminated string and its length;
 * NULL on allocation failure. */
static char *token_strip_joiners(const char *tok, size_t len,
                                 size_t *out_len)
{
    char *buf = malloc(len + 1);
    size_t b;
    size_t w = 0;
    if (buf == NULL) {
        return NULL;
    }
    for (b = 0; b < len; b++) {
        if (b + 2 < len && (unsigned char)tok[b] == 0xE2 &&
            (unsigned char)tok[b + 1] == 0x80 &&
            ((unsigned char)tok[b + 2] == 0x8C ||
             (unsigned char)tok[b + 2] == 0x8D)) {
            b += 2; /* skip the 3-byte sequence (loop adds 1) */
            continue;
        }
        buf[w++] = tok[b];
    }
    buf[w] = '\0';
    *out_len = w;
    return buf;
}

/* The post-filter of the UNICODE tokenizer, factored out
 * so the single-pass variant can derive the filtered list from the
 * unfiltered emission.  Semantics are byte-identical to the inline
 * block it replaces: keep tokens with > 1 code point (single-cp tokens
 * of bigram scripts are exempt), then drop pack stopwords.
 * strip_joiners removes U+200C/U+200D from tokens for the
 * MATCHING channel (display/raw tokens keep them; LANGUAGES.md
 * "stripped for matching in hi/bn/ur/ar").  Joined tokens always
 * have >= 2 flanking letters, so stripping never empties a token. */
static int unicode_post_filter(const str_list_t *in, odk_stopword_pack pack,
                               odk_language lang, const odk_rt_text *rt,
                               int strip_joiners, int morph_light,
                               str_list_t *out)
{
    size_t k;
    str_list_init(out);
    for (k = 0; k < in->count; k++) {
        const char *tok = in->items[k];
        size_t tok_len = strlen(tok);
        size_t eff_len = tok_len;
        char *owned = NULL; /* joiner-stripped and/or morphed copy */
        const char *eff = tok;
        size_t tok_cps;
        int exempt;
        int keep;
        if (strip_joiners && token_has_joiner(tok, tok_len)) {
            owned = token_strip_joiners(tok, tok_len, &eff_len);
            if (owned == NULL) {
                str_list_free(out);
                return -1;
            }
            eff = owned;
        }
        /* Light morphology in the matching channel; the
         * copy only allocates when a rule actually shortens the token
         * (the common no-rule case stays allocation-free). */
        if (morph_light && eff_len > 0 && eff_len < 256) {
            char tmp[256];
            size_t ml;
            memcpy(tmp, eff, eff_len);
            tmp[eff_len] = '\0';
            ml = odk_lang_morph_light(lang, tmp, eff_len);
            if (ml != eff_len) {
                char *grown = malloc(ml + 1);
                if (grown == NULL) {
                    free(owned);
                    str_list_free(out);
                    return -1;
                }
                memcpy(grown, tmp, ml);
                grown[ml] = '\0';
                free(owned);
                owned = grown;
                eff = owned;
                eff_len = ml;
            }
        }
        tok_cps = odk_utf8_codepoints(eff, eff_len);
        exempt = 0;
        if (tok_cps == 1) {
            uint32_t cp = 0;
            (void)odk_u_decode_next(eff, eff_len, &cp);
            exempt = odk_u_is_bigram_script(odk_u_script(cp));
        }
        keep = (tok_cps > 1 || exempt) &&
               !lang_stop_hit(pack, lang, rt, eff);
        if (keep) {
            if (str_list_push(out, eff, eff_len) != 0) {
                free(owned);
                str_list_free(out);
                return -1;
            }
        }
        free(owned);
    }
    return 0;
}

/* Single-pass text analysis.  Produces the UNFILTERED
 * token list (byte-identical to odk_extract_tokens_ex(..., 0, ...))
 * and the FILTERED token list (byte-identical to
 * odk_extract_tokens_ex(..., 1, ...)) from ONE tokenization pass, so
 * callers that need both channels (token counter + trigram counter)
 * tokenize each text once instead of twice.  Equivalence per path:
 *   - EN pack / ASCII: the legacy tokenizer's filtered mode emits exactly
 *     the len>1 non-stopword tokens of its unfiltered mode (the filter
 *     is applied inline with the same two predicates).
 *   - other packs: tokens_ascii_pack already emits unfiltered and
 *     applies the same two predicates for filtered mode.
 *   - UNICODE path: odk_extract_tokens_ex applies unicode_post_filter
 *     to the unfiltered emission for filtered mode.
 * The two channels are equivalent end to end. */
/* Single-pass text analysis.  Produces the
 * UNFILTERED token list (byte-identical to the unfiltered variant)
 * and the FILTERED token list derived by the SAME post-predicates the
 * filtered variant applies (one tokenization pass + one filter walk;
 * no second tokenize).  The _lang variant resolves AUTO per text.
 * UND keeps the exact baseline semantics (identity anchor). */
int odk_extract_tokens_both_morph(const char *text, odk_text_mode mode,
                                  odk_stopword_pack pack, odk_language lang,
                                  const odk_rt_text *rt, int morph_light,
                                  str_list_t *unfiltered,
                                  str_list_t *filtered)
{
    int rc;
    odk_language resolved = odk_lang_resolve(lang, text);
    int pure_ascii = 1;
    size_t len;
    size_t i;
    size_t k;

    str_list_init(unfiltered);
    str_list_init(filtered);
    if (text == NULL) {
        return 0;
    }
    rc = extract_tokens_core(text, mode, pack, resolved, rt, morph_light,
                            0, unfiltered);
    if (rc != 0) {
        str_list_free(unfiltered);
        str_list_free(filtered);
        return rc;
    }

    len = strlen(text);
    for (i = 0; i < len; i++) {
        if ((unsigned char)text[i] >= 0x80) {
            pure_ascii = 0;
            break;
        }
    }
    if (pure_ascii || mode == ODK_TEXT_ASCII_COMPAT) {
        /* same inline predicates the filtered ASCII variants apply */
        for (k = 0; k < unfiltered->count; k++) {
            const char *tok = unfiltered->items[k];
            size_t tok_len = strlen(tok);
            if (tok_len <= 1) {
                continue;
            }
            if (lang_stop_hit(pack, resolved, rt, tok)) {
                continue;
            }
            if (str_list_push(filtered, tok, tok_len) != 0) {
                str_list_free(unfiltered);
                str_list_free(filtered);
                return -1;
            }
        }
        return 0;
    }

    /* UNICODE path: derive via the shared post-filter (strips the
     * joiners for the matching channel when the resolved language is
     * a ZWJ-join pack) */
    {
        str_list_t kept;
        if (unicode_post_filter(unfiltered, pack, resolved, rt,
                                odk_lang_zwj_join(resolved),
                                morph_light, &kept) != 0) {
            str_list_free(unfiltered);
            str_list_free(filtered);
            return -1;
        }
        *filtered = kept;
    }
    return 0;
}

int odk_extract_tokens_both(const char *text, odk_text_mode mode,
                            odk_stopword_pack pack,
                            str_list_t *unfiltered, str_list_t *filtered)
{
    return odk_extract_tokens_both_morph(text, mode, pack, ODK_LANG_UND,
                                        NULL, 0, unfiltered, filtered);
}

/* The language-aware single-pass analysis with the DEFAULT
 * morphology setting (off) - the signature that tests and the brain
 * paths use.  The kernel passes its own knob through
 * odk_extract_tokens_both_morph. */
int odk_extract_tokens_both_lang(const char *text, odk_text_mode mode,
                                 odk_stopword_pack pack, odk_language lang,
                                 const odk_rt_text *rt,
                                 str_list_t *unfiltered,
                                 str_list_t *filtered)
{
    return odk_extract_tokens_both_morph(text, mode, pack, lang, rt, 0,
                                        unfiltered, filtered);
}

/* ------------------------------------------------------------------ */
/* Unicode trigram counter                                   */
/* ------------------------------------------------------------------ */

/* Pure-ASCII fast path: byte-identical to the legacy trigram channel. */
static int trigram_ascii(const char *text, cmap_t *map)
{
    str_list_t raw;
    sb_t normalized;
    size_t i;
    int failed = 0;

    str_list_init(&raw);
    if (odk_extract_tokens(text, 0, &raw) != 0) {
        cmap_free(map);
        return -1;
    }
    if (sb_init(&normalized) != 0) {
        str_list_free(&raw);
        cmap_free(map);
        return -1;
    }
    for (i = 0; i < raw.count; i++) {
        if (i > 0 && sb_putc(&normalized, ' ') != 0) {
            failed = 1;
            break;
        }
        if (sb_puts(&normalized, raw.items[i]) != 0) {
            failed = 1;
            break;
        }
    }
    str_list_free(&raw);
    if (!failed && normalized.len >= 3) { /* 3 bytes = 3 cps (ASCII) */
        size_t k;
        for (k = 0; k + 3 <= normalized.len; k++) {
            if (cmap_increment(map, normalized.data + k, 3) != 0) {
                failed = 1;
                break;
            }
        }
    }
    sb_free(&normalized);
    if (failed) {
        cmap_free(map);
    }
    return failed ? -1 : 0;
}

int odk_u_trigram_counter(const char *text, cmap_t *map)
{
    str_list_t raw;
    sb_t joined;
    size_t *offsets = NULL; /* byte offset of each code point */
    size_t off_cap = 0;
    size_t cp_count = 0;
    size_t i;
    int failed = 0;

    str_list_init(&raw);
    if (cmap_init(map) != 0) {
        return -1;
    }
    if (text == NULL) {
        return 0;
    }
    {
        size_t len = strlen(text);
        size_t k;
        int pure_ascii = 1;
        for (k = 0; k < len; k++) {
            if ((unsigned char)text[k] >= 0x80) {
                pure_ascii = 0;
                break;
            }
        }
        if (pure_ascii) {
            return trigram_ascii(text, map);
        }
    }

    /* Unicode path: unfiltered tokens joined with ' ', 3-cp windows */
    if (odk_extract_tokens_ex(text, ODK_TEXT_UNICODE, ODK_STOPWORDS_EN, 0,
                              &raw) != 0) {
        cmap_free(map);
        return -1;
    }
    if (sb_init(&joined) != 0) {
        str_list_free(&raw);
        cmap_free(map);
        return -1;
    }
    off_cap = 64;
    offsets = malloc(off_cap * sizeof(size_t));
    if (offsets == NULL) {
        sb_free(&joined);
        str_list_free(&raw);
        cmap_free(map);
        return -1;
    }
    for (i = 0; i < raw.count && !failed; i++) {
        size_t k = 0;
        size_t tok_len = strlen(raw.items[i]);
        if (i > 0) {
            if (sb_putc(&joined, ' ') != 0) {
                failed = 1;
                break;
            }
            if (cp_count == off_cap) {
                size_t *grown;
                if (off_cap > SIZE_MAX / 2 / sizeof(size_t)) {
                    failed = 1;
                    break;
                }
                off_cap *= 2;
                grown = realloc(offsets, off_cap * sizeof(size_t));
                if (grown == NULL) {
                    failed = 1;
                    break;
                }
                offsets = grown;
            }
            offsets[cp_count++] = joined.len - 1;
        }
        while (k < tok_len) {
            uint32_t cp;
            int used =
                odk_u_decode_next(raw.items[i] + k, tok_len - k, &cp);
            if (used == 0) {
                used = 1; /* tokens never contain invalid bytes */
            }
            if (sb_append(&joined, raw.items[i] + k, (size_t)used) != 0) {
                failed = 1;
                break;
            }
            if (cp_count == off_cap) {
                size_t *grown;
                if (off_cap > SIZE_MAX / 2 / sizeof(size_t)) {
                    failed = 1;
                    break;
                }
                off_cap *= 2;
                grown = realloc(offsets, off_cap * sizeof(size_t));
                if (grown == NULL) {
                    failed = 1;
                    break;
                }
                offsets = grown;
            }
            offsets[cp_count++] = joined.len - (size_t)used;
            k += (size_t)used;
        }
    }
    str_list_free(&raw);
    if (!failed && cp_count >= 3) {
        for (i = 0; i + 3 <= cp_count; i++) {
            size_t start = offsets[i];
            size_t end = (i + 3 < cp_count) ? offsets[i + 3] : joined.len;
            if (cmap_increment(map, joined.data + start, end - start) != 0) {
                failed = 1;
                break;
            }
        }
    }
    free(offsets);
    sb_free(&joined);
    if (failed) {
        cmap_free(map);
        return -1;
    }
    return 0;
}
